import{_ as t,o as r,c as a,a3 as n}from"./chunks/framework.fntC-tS-.js";const o="/images/sgc_symp24_banner.png",s="/images/SGC_symp24_ageospatial.png",i="/images/sgc_symp24_Flyer_1.png",l="/images/sgc_symp24_Flyer_2.png",b=JSON.parse('{"title":"Symposium on Bridging Modelling and Data Sciences","description":"","frontmatter":{"title":"Symposium on Bridging Modelling and Data Sciences","date":"2024-11-21T00:00:00.000Z","tags":["Event"]},"headers":[],"relativePath":"events/sgc-symposium24.md","filePath":"events/sgc-symposium24.md","lastUpdated":1794345340000}'),d={name:"events/sgc-symposium24.md"};function h(p,e,c,g,m,u){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="symposium-on-bridging-modelling-and-data-sciences" tabindex="-1">Symposium on Bridging Modelling and Data Sciences <a class="header-anchor" href="#symposium-on-bridging-modelling-and-data-sciences" aria-label="Permalink to &quot;Symposium on Bridging Modelling and Data Sciences&quot;">​</a></h1><p><img src="'+o+'" alt="Symposium banner"></p><h2 id="general-information" tabindex="-1">General information <a class="header-anchor" href="#general-information" aria-label="Permalink to &quot;General information&quot;">​</a></h2><p>The Swiss Geocomputing Centre (SGC) invites you to the symposium <strong>Bridging Modelling and Data Sciences in the Geosciences</strong>, taking place on <strong>November 21-22, 2024</strong> at the University of Lausanne.</p><p>The event will feature engaging <a href="#program">talks and workshops</a> on topics tackling reproducibility in the geoscientific domain, integrating geospatial data into ML/AI workflows, geocomputation for weather and climate modelling, applications in the insurance domain, and green IT, amongst others.</p><p>This symposium aims to provide a dynamic venue for showcasing research, fostering interdisciplinary dialogue, and building connections between academia, industry, and public sectors. We welcome students and researchers to participate and invite you to contribute in a <a href="#posters">poster session</a>.</p><blockquote><p><strong>Infos</strong></p><p>🔎 <strong>Location:</strong> University of Lausanne (Amphipole, Geopolis, IDHEAP) - <strong>on-site event</strong></p><p>📅 <strong>Dates:</strong> 21-22 November 2024</p><p>✅ <strong>Registration (deadline extended to 15 Nov. 24):</strong> <a href="#registration">Register here</a> <em>(the event is free but <a href="#registration">registration is mandatory</a>)</em></p></blockquote><h2 id="program" tabindex="-1">Program <a class="header-anchor" href="#program" aria-label="Permalink to &quot;Program&quot;">​</a></h2><h3 id="day-1-thursday-21-november-2024" tabindex="-1">Day 1 - Thursday, 21 November 2024 <a class="header-anchor" href="#day-1-thursday-21-november-2024" aria-label="Permalink to &quot;Day 1 - Thursday, 21 November 2024&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>Time</strong></th><th><strong>Event</strong></th></tr></thead><tbody><tr><td>9:30 - 10:00</td><td>☕ Registration with coffee (<a href="https://planete.unil.ch/?local=POL-210" target="_blank" rel="noreferrer">Amphipole 210</a>)</td></tr><tr><td>10:00 - 10:30</td><td>Welcome message by <a href="https://applicationspub.unil.ch/interpub/noauth/php/Un/UnPers.php?PerNum=1048878&amp;LanCode=37" target="_blank" rel="noreferrer">Céline Rozenblat</a> - Vice Dean FGSE</td></tr><tr><td></td><td><strong>Keynote presentations</strong> (<a href="https://planete.unil.ch/?local=POL-210" target="_blank" rel="noreferrer">Amphipole 210</a>)</td></tr><tr><td>10:30 - 11:15</td><td><strong>Reproducibility in Geospatial Sector: Needs and Challenges</strong> <br> <em><a href="https://www.supsi.ch/en/cc-os" target="_blank" rel="noreferrer">CC-OS</a>, <a href="https://www.supsi.ch/massimiliano-cannata" target="_blank" rel="noreferrer">Massimiliano Cannata</a></em></td></tr><tr><td>11:15 - 12:00</td><td><strong>Digital Twins of the Atmosphere in the Era of Machine Learning</strong> <br> <em><a href="https://www.nvidia.com/en-us/" target="_blank" rel="noreferrer">Nvidia Research</a>, <a href="https://research.nvidia.com/person/boris-bonev" target="_blank" rel="noreferrer">Boris Bonev</a></em></td></tr><tr><td>12:00 - 12:45</td><td><strong>AI in Environmental Sciences at the SDSC</strong> <br> <em><a href="https://www.datascience.ch/" target="_blank" rel="noreferrer">SDSC</a>, <a href="https://www.datascience.ch/people/ekaterina-krymova" target="_blank" rel="noreferrer">Ekaterina Krymova</a></em></td></tr><tr><td>12:45 - 13:45</td><td>🍝 Lunch break</td></tr><tr><td></td><td>💻 <strong>Workshops</strong> (<a href="https://planete.unil.ch/?batiment=GEO" target="_blank" rel="noreferrer">Geopolis</a>)</td></tr><tr><td>14:00 - 17:30</td><td><a href="#nvidia">Nvidia</a> (<a href="https://planete.unil.ch/?local=GEO-2121" target="_blank" rel="noreferrer">Geopolis 2121</a>) <br> <a href="#osires">OSiRES</a>/<a href="#ageospatial">Ageospatial</a> (<a href="https://planete.unil.ch/?local=GEO-2129" target="_blank" rel="noreferrer">Geopolis 2129</a>)</td></tr><tr><td>17:30 - 18:30</td><td>🍺 Aperitif</td></tr></tbody></table><h3 id="day-2-friday-22-november-2024" tabindex="-1">Day 2 - Friday, 22 November 2024 <a class="header-anchor" href="#day-2-friday-22-november-2024" aria-label="Permalink to &quot;Day 2 - Friday, 22 November 2024&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>Time</strong></th><th><strong>Event</strong></th></tr></thead><tbody><tr><td>9:00 - 9:15</td><td>☕ Welcome with coffee (<a href="https://planete.unil.ch/?batiment=IDP" target="_blank" rel="noreferrer">IDHEAP</a>)</td></tr><tr><td>9:15 - 9:30</td><td><strong>Reproducible Science in Publications - Example from the <a href="https://www.geoscientific-model-development.net/" target="_blank" rel="noreferrer">GMD Journal</a></strong> <br> <em>Unil - SGC, <a href="https://github.com/luraess" target="_blank" rel="noreferrer">Ludovic Räss</a></em></td></tr><tr><td></td><td><strong>Talks</strong> (<a href="https://planete.unil.ch/?batiment=IDP" target="_blank" rel="noreferrer">IDHEAP</a>)</td></tr><tr><td>9:30 - 10:00</td><td><strong>GeoForge - Making Geospatial Data Speak to AI</strong> <br> <em><a href="https://www.ageospatial.com/" target="_blank" rel="noreferrer">Ageospatial</a>, <a href="https://www.linkedin.com/in/maaz-sheikh99/" target="_blank" rel="noreferrer">Maaz Sheikh</a></em></td></tr><tr><td>10:00 - 10:30</td><td><strong>Zenodo for geosciences</strong> <br> <em><a href="https://zenodo.org/" target="_blank" rel="noreferrer">Zenodo</a>, <a href="https://sparks.cern/nielsen-lars" target="_blank" rel="noreferrer">Lars Holm Nielsen</a> (Head Open Science at CERN)</em></td></tr><tr><td>10:30 - 11:00</td><td><strong>GreenIT - challenges and best practices for geocomputing sector</strong> <br> <em><a href="https://www.resilio.com/" target="_blank" rel="noreferrer">Resilio</a>, Rosendo Mañas Faura</em></td></tr><tr><td>11:00 - 11:30</td><td>☕ Coffee break</td></tr><tr><td>11:30 - 12:00</td><td><strong>Geocomputational needs for climate extremes modeling</strong> <br> <em><a href="https://applicationspub.unil.ch/interpub/noauth/php/Un/UnUnite.php?UnId=394&amp;LanCode=8" target="_blank" rel="noreferrer">ECCE</a>, <a href="https://applicationspub.unil.ch/interpub/noauth/php/Un/UnPers.php?PerNum=1263941&amp;LanCode=8" target="_blank" rel="noreferrer">Erwan Koch</a></em></td></tr><tr><td>12:00 - 12:30</td><td><strong>Geodata Analysis &amp; Data-Driven Solutions for Swiss Insurance: ECA Experience</strong> <br> <em><a href="https://www.eca-vaud.ch/" target="_blank" rel="noreferrer">ECA</a>, <a href="https://ch.linkedin.com/in/carmen-vega-orozco-a681b424" target="_blank" rel="noreferrer">Carmen Vega</a></em></td></tr><tr><td></td><td><strong>Poster session</strong> (<a href="https://planete.unil.ch/?batiment=IDP" target="_blank" rel="noreferrer">IDHEAP</a>)</td></tr><tr><td>12:30 - 13:30</td><td>Poster 2-minute madness</td></tr><tr><td>13:30 - 15:30</td><td><a href="#posters">Poster session</a> &amp; 🍔 finger food</td></tr><tr><td>15:30 - 16:00</td><td>Closing remarks</td></tr></tbody></table><h3 id="workshops-thursday-21-november-2024" tabindex="-1">Workshops - Thursday, 21 November 2024 <a class="header-anchor" href="#workshops-thursday-21-november-2024" aria-label="Permalink to &quot;Workshops - Thursday, 21 November 2024&quot;">​</a></h3><h4 id="nvidia" tabindex="-1">Nvidia <a class="header-anchor" href="#nvidia" aria-label="Permalink to &quot;Nvidia&quot;">​</a></h4><p>Unlocking the Power of Deep Learning for Weather Forecasting: A Hands-on Workshop with Earth-2</p><p><strong>Details:</strong> The workshop provides a step-by-step overview of the fundamentals of deep neural networks, walks attendees through the hands-on experience of building and improving deep learning models applied to weather forecast using a framework that uses the fundamental laws of physics to model the behavior of complex systems, and enables attendees to visualize the physically accurate outputs of the trained model in near real-time.</p><p><strong>Instructor:</strong> <a href="https://www.linkedin.com/in/abouzar-ghasemi-a204013b/" target="_blank" rel="noreferrer">Abouzar Ghasemi</a></p><blockquote><p>💡 Participants interested in joining this workshop will be required to register for that in order to have access to the GPU compute resources for the workshop.</p></blockquote><h4 id="osires" tabindex="-1">OSiRES <a class="header-anchor" href="#osires" aria-label="Permalink to &quot;OSiRES&quot;">​</a></h4><p>Demonstrating the utilisation of geospatial webservices for reproducible research</p><p><strong>Details:</strong> While modern Spatial Data Infrastructures (e.g. swisstopo or INSPIRE) use interoperable web services and open standards to serve large datasets, they lack the ability to retrieve geodata as it existed at a specific point in time, refer to its status at that instant, and ensure its immutability. OSIReS is a project co-financed by swissuniversities in the frame of its Programme Open Science I, Phase B, that aims at tackle this issue. In this workshop, after presenting the project during the Keynote session, we will demonstrate and discuss the needs and challenges regarding the utilisation of geospatial webservices for reproducible research.</p><p><strong>Instructor:</strong> <a href="https://people.hes-so.ch/de/profile/2912116448-jens-ingensand" target="_blank" rel="noreferrer">Jens Ingensand</a></p><h4 id="ageospatial" tabindex="-1">Ageospatial <a class="header-anchor" href="#ageospatial" aria-label="Permalink to &quot;Ageospatial&quot;">​</a></h4><p>Building the future of GeoForge: An interactive workshop on Generative AI usage in geospatial data assisted disaster management.</p><p><img src="'+s+'" alt="Ageospatial"></p><p><strong>Details:</strong> Participants will have the opportunity to test the GeoForge proof of concept. Ageospatial aims to gather valuable feedback and collaborate on ideas on how this future platform can provide real value in tackling current challenges, especially in disaster management and risk fields. We&#39;ll present use cases and invite participants to propose concrete improvements and suggest architectures for new AI frameworks such as Agentic AI systems, RAG concepts, and LangChain frameworks.</p><p><strong>Instructor:</strong> <a href="https://www.linkedin.com/in/maaz-sheikh99/" target="_blank" rel="noreferrer">Maaz Sheikh</a></p><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p>The symposium is completely free of charge. On site, you will be able to attend any sessions you like, but for logistical reasons please indicate through the form which sessions you are interested in.</p><p>✅ <a href="https://events.unil.ch/register/377" target="_blank" rel="noreferrer"><strong>Register here</strong> (deadline extended to 15 Nov. 24) 👈</a></p><blockquote><p>❓ <strong>Questions.</strong> For any further question about the event, contact <a href="mailto:geocomputing@unil.ch" target="_blank" rel="noreferrer">geocomputing@unil.ch</a>.</p></blockquote><h2 id="posters" tabindex="-1">Posters <a class="header-anchor" href="#posters" aria-label="Permalink to &quot;Posters&quot;">​</a></h2><p>If you wish to present your past or ongoing research with a poster on Friday afternoon, please indicate so in the registration form. There are still many slots available for poster presentations.</p><blockquote><p>💡 <strong>We encourage you to sign up and to re-use a poster you did present at a recent conference or event!</strong></p><p>Poster format: A0 portrait (other format could be accommodated as well)</p></blockquote><p>The poster session will be divided into two parts. First, each presenter will give a 2-minute presentation on a screen to introduce their research and provide context. For the remainder of the afternoon, attendees will be free to walk around, ask questions, and create network connections.</p><h2 id="announce" tabindex="-1">Announce <a class="header-anchor" href="#announce" aria-label="Permalink to &quot;Announce&quot;">​</a></h2><p><img src="'+i+'" alt="Symposium flyer, page 1"><img src="'+l+'" alt="Symposium flyer, page 2"></p>',37)])])}const k=t(d,[["render",h]]);export{b as __pageData,k as default};
